313:/**
314: * The places a posting names, read off `location` and the reach it reported.
315: *
316: * `remoteScope` is the posting speaking about itself and so is read first:
317: * `worldwide` means the location field is describing where the company sits,
318: * not where the candidate must be — the exact over-block that would otherwise
319: * close every job at a US-headquartered company that hires globally.
320: */
321:export function namedPlaces(
322:  text: string | null | undefined,
323:  remoteScope?: string | null,
324:): NamedPlaces {
325:  const scope = (remoteScope ?? "").trim().toLowerCase();
326:  const raw = (text ?? "").trim();
327:  const countries: string[] = [];
328:  const regions: string[] = [];
329:  let open = scope === "worldwide";
330:
331:  if (raw) {
332:    if (!open) open = OPEN_WORDS.some((w) => hasWord(raw, w));
333:    if (namesUnitedStates(raw)) countries.push("United States");
334:    for (const [country, aliases] of Object.entries(COUNTRY_ALIASES)) {
335:      if (countries.includes(country)) continue;
336:      if (aliases.some((a) => hasWord(raw, a))) countries.push(country);
337:    }
338:    for (const c of countriesFromCodes(raw)) {
339:      if (!countries.includes(c)) countries.push(c);
340:    }
341:    for (const [region, aliases] of Object.entries(REGION_ALIASES)) {
342:      if (aliases.some((a) => hasWord(raw, a))) regions.push(region);
343:    }
344:  }
345:
346:  if (scope === "us_only" && !countries.includes("United States")) {
347:    countries.push("United States");
348:  }
349:  if (scope === "latam" && !regions.includes("latam")) regions.push("latam");
350:
351:  return { countries, regions, open };
352:}
